/// One real jigsaw piece: its outline inside the picture.
class JigsawPiece {
  const JigsawPiece(this.x0, this.y0, this.x1, this.y1, this.points);

  /// Bounding box of the outline, as fractions of the picture.
  final double x0;
  final double y0;
  final double x1;
  final double y1;

  /// Outline as x, y, x, y ... fractions of the picture.
  final List<double> points;

  double get width => x1 - x0;
  double get height => y1 - y0;

  /// The outline for a picture drawn `size` pixels wide and tall, with the
  /// piece's own top-left corner at (0, 0).
  Path path(double size) {
    final Path p = Path();
    for (int i = 0; i < points.length; i += 2) {
      final double x = (points[i] - x0) * size;
      final double y = (points[i + 1] - y0) * size;
      if (i == 0) {
        p.moveTo(x, y);
      } else {
        p.lineTo(x, y);
      }
    }
    return p..close();
  }
}

/// A picture cut into jigsaw pieces.
class JigsawCut {
  const JigsawCut({
    required this.asset,
    required this.title,
    required this.rows,
    required this.cols,
    required this.pieces,
  });

  final String asset;
  final String title;
  final int rows;
  final int cols;
  final List<JigsawPiece> pieces;
}

